test('default', async ({ page }) => {
  await page.goto('/')
  await expect.poll(async () => page.evaluate(() => document.body.children.length)).toEqual(7)
  await expect.poll(async () => page.evaluate(() => window.tw.instances.size)).toEqual(4)

  // Get actual rules from the page.
  const actualRules = {
    document: await page.evaluate(getRules, 0),
    shadow: await page.evaluate(getRules, 1),
  }

  const actualCss = {
    document: actualRules.document.join('\n'),
    shadow: actualRules.shadow.join('\n'),
  }

  // Make sure there are no empty rules.
  const emptyRules = []
  for (const rule of actualRules.document) {
    if (rule.includes('{ }')) {
      emptyRules.push(rule)
    }
  }
  await expect(emptyRules).toEqual([])

  // Create expected files if they don't exist.
  if (!fs.existsSync('src/test/cases/expected-document.css') || !fs.existsSync('src/test/cases/expected-shadow.css')) {
    fs.writeFileSync('src/test/cases/expected-document.css', actualCss.document)
    fs.writeFileSync('src/test/cases/expected-shadow.css', actualCss.shadow)
  }

  // Get expected rules from files.
  const expectedCss = {
    document: fs.readFileSync('src/test/cases/expected-document.css', 'utf8'),
    shadow: fs.readFileSync('src/test/cases/expected-shadow.css', 'utf8'),
  }

  // Compare CSS.
  await expect(actualCss.document).toEqual(expectedCss.document)
  await expect(actualCss.shadow).toEqual(expectedCss.shadow)
})

